films.push({"id":"the-way-forward","title":"The Way Forward","creator":"Moving Works","runtime":"08:27","language":"English","kind":"Documentary testimony","tags":["Faith","Work","Trust"],"summary":"A Texas cattleman reflects on caring for his herd, admitting his limits and turning to prayer and Scripture during everyday work.","contentNote":"Includes ranch and cattle-handling scenes and Christian reflection on suffering and the death of Jesus. The linked upload includes a closing Moving Works subscription and donation appeal.","youtube":"https://www.youtube.com/watch?v=1dIE5bsGjUQ","source":"https://movingworks.org/films/the-way-forward","thumbnailSource":"https://cdn.prod.website-files.com/68e6c536afd77c2cc03e6998/699de8da3879dfd2067181e2_The-Way-Forward-WF.jpg","checked":"2026-11-08","runtimeEvidence":"Official Moving Works film page embeds this exact upload and labels its unsubtitled original English. Full authored English transcript reviewed. Actual507.921seconds, displayed8:27afterload (initialrounding8:28). Original non-ad advancing film, openingcoffee/ranch, midwork, closingScripture, ministryappeal and ended507.921player pixels checked8November2026. SermonCentral lists a7:50version; this entry uses the longer exactcreatorlinkedYouTubeupload includingclosingappeal.","image":"data:image/jpeg;base64,","checkedDisplay":"8 November 2026"});
films.push({"id":"spirit-of-prayer","title":"Spirit of Prayer","creator":"Moving Works","runtime":"01:59","language":"English","kind":"Documentary short","tags":["Prayer","Faith","Hope"],"summary":"Egyptian Christians reflect on united prayer and their hope in God during a period of political unrest. A short film derived from Eyes Open.","contentNote":"Historical testimony with protest, crowds and unrest imagery. Statements about Egypt, church attendance and conversions reflect the speakers' experiences at the time, not current conditions or verified statistics.","youtube":"https://www.youtube.com/watch?v=xR2zlIWEyNQ","source":"https://movingworks.org/films/spirit-of-prayer","thumbnailSource":"https://cdn.prod.website-files.com/68e6c536afd77c2cc03e6998/699de6163f06a9859049f53d_Spirit-of-Prayer-WF.jpg","checked":"2026-11-08","runtimeEvidence":"Exact upload linked by official Moving Works page; official download table labels English / No Subtitles. Authored English transcript reviewed from0:04to1:50. Actual119.954seconds, displayed1:59; title describes two-minute short. Original opening, midfilm, closing and ended state checked8November2026. Derived from Eyes Open, not the longer original.","image":"data:image/jpeg;base64,","checkedDisplay":"8 November 2026"});
films.push({"id":"christmas-exodus","title":"Christmas Exodus","creator":"Love Black Country Creatives","runtime":"03:55","language":"English","kind":"Narrative film","tags":["Hope","Christmas","Community"],"summary":"Four people face a difficult Christmas during the 2020 pandemic. A neighbour's kindness connects their different journeys home with the Christian message of Immanuel, God with us.","contentNote":"Text-led Christmas story with a song, pandemic isolation, work worries and a closing invitation to local churches. English on-screen text; not a dialogue-led film. The setting and support links are from 2020, not current public-health guidance or a verified present-day referral.","youtube":"https://www.youtube.com/watch?v=QTM-EqICcA0","source":"https://www.blepo.co/portfolio/christmas-advert/","runtimeEvidence":"Exact Love Black Country upload embedded in Blepo's project portfolio, which names Love Black Country as client. Creator's Christmas Exodus project page and 14 December 2020 release announcement identify the full four-minute film. Actual235.542seconds, displayed3:55; original non-ad opening, middle, closing and ended state checked8November2026. English on-screen story text inspected; English auto-captioned song reviewed0:04-3:55. Language here describes the text-led presentation, not a spoken-dialogue claim.","checkedDisplay":"8 November 2026","image":"data:image/jpeg;base64,"});
