films.push({"id":"then-god-changed-everything","title":"Then God Changed Everything","creator":"Moving Works","runtime":"01:59","language":"English","kind":"Documentary testimony","tags":["Faith","Service","Trust"],"summary":"Gary and Peggy reflect on leaving a comfortable life in Illinois to serve in Ethiopia through a school and Christian mission. A two-minute short derived from Gary & Peggy.","contentNote":"Historical missionary testimony with children, poverty and food-need references. Statements about the school, local faith communities and spiritual outcomes are the speakers' experiences at the time, not verified current conditions or a referral to services.","youtube":"https://www.youtube.com/watch?v=WbPuoUlYHCs","source":"https://movingworks.org/films/then-god-changed-everything","thumbnailSource":"https://cdn.prod.website-files.com/68e6c536afd77c2cc03e6998/699de9167d2b50b8db94e695_Then-God-Changed-Everything-WF.jpg","checked":"2026-11-08","checkedDisplay":"8 November 2026","runtimeEvidence":"Official Moving Works page embeds this exact upload and labels the unsubtitled original English. Full authored English transcript reviewed0:10-1:43. Exact119.351seconds, displayed1:59; creator describes a two-minute short derived from Gary & Peggy, not the distributor's5:02 full film. Original non-ad opening, middle, closing and ended state checked8November2026.","image":"data:image/jpeg;base64,"});
